var maxScore = function(nums) {
    const m = nums.length;
    const size = 1 << m;
    const dp = new Array(size).fill(0);
    // precompute gcd
    const gcd = (a, b) => b === 0 ? a : gcd(b, a % b);
    const g = Array.from({length: m}, () => new Array(m).fill(0));
    for (let i = 0; i < m; i++)
        for (let j = i + 1; j < m; j++)
            g[i][j] = g[j][i] = gcd(nums[i], nums[j]);

