/**
 * @param {number[]} nums
 * @return {number}
 */
var maxScore = function(nums) {
    const m = nums.length;
    const size = 1 << m;
    const dp = new Array(size).fill(0);

    const gcd = (a, b) => {
        while (b !== 0) {
            const t = a % b;
            a = b;
            b = t;
        }
        return a;
    };

    // Precompute gcd for all pairs
    const g = Array.from({ length: m }, () => new Array(m).fill(0));
    for (let i = 0; i < m; i++) {
        for (let j = i + 1; j < m; j++) {
            g[i][j] = g[j][i] = gcd(nums[i], nums[j]);
        }
    }

    for (let mask = 0; mask < size; mask++) {
        // Count used bits
        let cnt = 0;
        let t = mask;
        while (t > 0) {
            t &= t - 1;
            cnt++;
        }
        if (cnt % 2 !== 0) continue; // must have used an even number of elements
        const op = cnt / 2 + 1;      // current operation index (1-indexed)

        // Pick the first unused element and pair it with every other unused element
        for (let i = 0; i < m; i++) {
            if (mask & (1 << i)) continue;
            for (let j = i + 1; j < m; j++) {
                if (mask & (1 << j)) continue;
                const newMask = mask | (1 << i) | (1 << j);
                const score = dp[mask] + op * g[i][j];
                if (score > dp[newMask]) dp[newMask] = score;
            }
            break;
        }
    }

    return dp[size - 1];
};
```

