var isSolvable = function(words, result) {
    const all = words.concat([result]);
    const charIndex = new Map();
    for (const w of all) {
        for (const ch of w) {
            if (!charIndex.has(ch)) charIndex.set(ch, charIndex.size);
        }
    }
    const n = charIndex.size;
    if (n > 10) return false;

    const isLead = new Array(n).fill(false);
    for (const w of all) isLead[charIndex.get(w[0])] = true;

    let maxWordLen = 0;
    for (const w of words) if (w.length > maxWordLen) maxWordLen = w.length;
    const totalCols = Math.max(maxWordLen, result.length);

    const cols = [];
    for (let c = 0; c < totalCols; c++) {
        const col = [];
        for (const w of words) {
            if (w.length > c) col.push(charIndex.get(w[w.length - 1 - c]));
        }
        cols.push(col);
    }
    const resCol = new Array(totalCols).fill(-1);
    for (let c = 0; c < result.length; c++) {
        resCol[c] = charIndex.get(result[result.length - 1 - c]);
    }

    const mapping = new Array(n).fill(-1);
    const used = new Array(10).fill(false);

    const dfs = (col, carry) => {
        if (col === totalCols) return carry === 0;
        const colChars = cols[col];
        const unassigned = [];
        for (let k = 0; k < colChars.length; k++) {
            const ci = colChars[k];
            if (mapping[ci] === -1 && unassigned.indexOf(ci) < 0) unassigned.push(ci);
        }
        const m = unassigned.length;

        const assign = (i) => {
            if (i === m) {
                let sum = carry;
                for (let k = 0; k < colChars.length; k++) sum += mapping[colChars[k]];
                const digit = sum % 10;
                const newCarry = (sum - digit) / 10;
                const resChar = resCol[col];
                if (resChar < 0) {
                    return digit === 0 && dfs(col + 1, newCarry);
                }
                const rd = mapping[resChar];
                if (rd >= 0) {
                    return rd === digit && dfs(col + 1, newCarry);
                }
                if (used[digit] || (digit === 0 && isLead[resChar])) return false;
                mapping[resChar] = digit;
                used[digit] = true;
                const ok = dfs(col + 1, newCarry);
                used[digit] = false;
                mapping[resChar] = -1;
                return ok;
            }
            const ci = unassigned[i];
            const start = isLead[ci] ? 1 : 0;
            for (let d = start; d <= 9; d++) {
                if (used[d]) continue;
                mapping[ci] = d;
                used[d] = true;
                if (assign(i + 1)) return true;
                used[d] = false;
                mapping[ci] = -1;
            }
            return false;
        };

        return assign(0);
    };

    return dfs(0, 0);
};
