```javascript
/**
 * @param {number[]} arr
 * @return {number}
 */
var numFactoredBinaryTrees = function(arr) {
    const MOD = 1000000007;
    arr.sort((a, b) => a - b);
    const n = arr.length;
    const dp = new Array(n).fill(1);
    const index = new Map();
    for (let i = 0; i < n; i++) {
        index.set(arr[i], i);
    }

    // Exact (a * b) % MOD for a, b < 2^30 using 15-bit splitting to avoid
    // floating-point precision loss beyond 2^53.
    const mulmod = (a, b) => {
        const a1 = Math.floor(a / 32768);
        const a0 = a - a1 * 32768;
        return (((a1 * b) % MOD) * 32768 + a0 * b) % MOD;
    };

    for (let i = 0; i < n; i++) {
        for (let j = 0; j < i; j++) {
            if (arr[i] % arr[j] === 0) {
                const k = index.get(arr[i] / arr[j]);
                if (k !== undefined) {
                    dp[i] = (dp[i] + mulmod(dp[j], dp[k])) % MOD;
                }
            }
        }
    }

    let result = 0;
    for (let i = 0; i < n; i++) {
        result = (result + dp[i]) % MOD;
    }
    return result;
};
```

