var evaluate = function(s, knowledge) {
    const map = new Map();
    for (const [key, value] of knowledge) {
        map.set(key, value);
    }

    let result = [];
    let i = 0;
    const n = s.length;

    while (i < n) {
        if (s[i] === '(') {
