    const n = graph.length;
    const color = new Array(n).fill(0); // 0 unvisited, 1 visiting, 2 safe
    const dfs = (node) => {
        if (color[node] > 0) return color[node] === 2;
        color[node] = 1;
        for (const next of graph[node]) {
            if (!dfs(next)) return false; // but need to not reset color... actually color stays 1 for unsafe
        }
        color[node] = 2;
        return true;
    };
    const res = [];
    for (let i = 0; i < n; i++) if (dfs(i)) res.push(i);
    return res;
};
```

