var canCross = function(stones) {
    const n = stones.length;

    // First jump must be exactly 1 unit, so a stone must exist at position 1.
    if (stones[1] !== 1) return false;

    // Map each stone position to its index for O(1) lookups.
    const indexOf = new Map();
    for (let i = 0; i < n; i++) indexOf.set(stones[i], i);

    // dp[i][k] = 1 if stone i is reachable with the last jump being k units.
    // Reaching stone index i with jump k requires k <= i <= n - 1.
    const dp = new Array(n);
    for (let i = 0; i < n; i++) dp[i] = new Uint8Array(n + 1);
