```javascript
var largestMagicSquare = function(grid) {
    const m = grid.length, n = grid[0].length;

    // Prefix sums
    // rowPrefix[i][j] = sum of grid[i][0..j-1]
    const rowPre = Array.from({length: m}, () => new Array(n + 1).fill(0));
    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            rowPre[i][j + 1] = rowPre[i][j] + grid[i][j];
        }
    }
    // colPrefix[i][j] = sum of grid[0..i-1][j]
    const colPre = Array.from({length: m + 1}, () => new Array(n).fill(0));
    for (let j = 0; j < n; j++) {
        for (let i = 0; i < m; i++) {
            colPre[i + 1][j] = colPre[i][j] + grid[i][j];
        }
    }

    const rowSum = (i, j, k) => rowPre[i][j + k] - rowPre[i][j];
    const colSum = (i, j, k) => colPre[i + k][j] - colPre[i][j];

    const check = (i, j, k) => {
        const target = rowSum(i, j, k);
        // Check rows
        for (let r = i + 1; r < i + k; r++) {
            if (rowSum(r, j, k) !== target) return false;
        }
        // Check columns
        for (let c = j; c < j + k; c++) {
            if (colSum(i, c, k) !== target) return false;
        }
        // Check main diagonal
        let d1 = 0, d2 = 0;
        for (let t = 0; t < k; t++) {
            d1 += grid[i + t][j + t];
            d2 += grid[i + t][j + k - 1 - t];
        }
        return d1 === target && d2 === target;
    };

    for (let k = Math.min(m, n); k >= 2; k--) {
        for (let i = 0; i + k <= m; i++) {
            for (let j = 0; j + k <= n; j++) {
                if (check(i, j, k)) return k;
            }
        }
    }
    return 1;
};
```

