var maxPoints = function(points) {
    const n = points.length;
    if (n <= 2) return n;

    const gcd = (a, b) => {
        a = Math.abs(a);
        b = Math.abs(b);
        while (b !== 0) {
            const t = a % b;
            a = b;
            b = t;
        }
        return a;
    };

    let best = 1;

    for (let i = 0; i < n; i++) {
        const slopeMap = new Map();
        let duplicates = 0;
        let localMax = 0;
        const xi = points[i][0];
        const yi = points[i][1];

        for (let j = 0; j < n; j++) {
            if (j === i) continue;

            const dx = points[j][0] - xi;
            const dy = points[j][1] - yi;

            if (dx === 0 && dy === 0) {
                duplicates++;
                continue;
            }

            const g = gcd(dx, dy);
            let sx = dx / g;
            let sy = dy / g;

            if (sx < 0 || (sx === 0 && sy < 0)) {
                sx = -sx;
                sy = -sy;
            }

            const key = sx + ',' + sy;
            const count = (slopeMap.get(key) || 0) + 1;
            slopeMap.set(key, count);
            if (count > localMax) localMax = count;
        }

        const total = localMax + duplicates + 1;
        if (total > best) best = total;
    }

    return best;
};
```

