function solveLinear(arr, k) {
  const m = arr.length;
  const NEG = -1e15; // use a very negative number instead of -Infinity to avoid NaN from adding
  const dp = [];
  for (let i = 0; i <= m; i++) dp.push(new Array(k+1).fill(NEG));
