Alternative common implementation (from LeetCode solutions):

var maxSizeSlices = function(slices) {
  const m = slices.length, n = m / 3;
  const helper = (arr) => {
    const len = arr.length;
    // dp[j][i]: max sum picking j non-adjacent from first i
    const dp = Array.from({length: n+1}, () => new Array(len+1).fill(0));
    // dp[0][i] = 0
    for (let j = 1; j <= n; j++) {
      for (let i = 1; i <= len; i++) {
        dp[j][i] = Math.max(dp[j][i-1], (i >= 2 ? dp[j-1][i-2] : j === 1 ? 0 : -Infinity) + arr[i-1]);
      }
    }
    return dp[n][len];
  };
