/**
 * @param {string[]} grid
 * @return {number}
 */
var regionsBySlashes = function(grid) {
    const n = grid.length;
    const total = n * n * 4;
    const parent = new Array(total);
    const rank = new Array(total).fill(0);
    for (let i = 0; i < total; i++) parent[i] = i;

    const find = (x) => {
        while (parent[x] !== x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    };

    const union = (a, b) => {
        const ra = find(a);
        const rb = find(b);
        if (ra === rb) return;
        if (rank[ra] < rank[rb]) {
            parent[ra] = rb;
        } else if (rank[ra] > rank[rb]) {
            parent[rb] = ra;
        } else {
            parent[rb] = ra;
            rank[ra]++;
        }
    };

    const id = (i, j, t) => (i * n + j) * 4 + t;

    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
            const c = grid[i][j];
            if (c === '/') {
                union(id(i, j, 0), id(i, j, 3));
                union(id(i, j, 1), id(i, j, 2));
            } else if (c === '\\') {
                union(id(i, j, 0), id(i, j, 1));
                union(id(i, j, 2), id(i, j, 3));
            } else {
                union(id(i, j, 0), id(i, j, 1));
                union(id(i, j, 1), id(i, j, 2));
                union(id(i, j, 2), id(i, j, 3));
            }
            if (j + 1 < n) union(id(i, j, 1), id(i, j + 1, 3));
            if (i + 1 < n) union(id(i, j, 2), id(i + 1, j, 0));
        }
    }

    let regions = 0;
    for (let i = 0; i < total; i++) {
        if (find(i) === i) regions++;
    }
    return regions;
};
```

