var removeInvalidParentheses = function(s) {
    let l = 0, r = 0;
    for (const c of s) {
        if (c === '(') l++;
        else if (c === ')') { if (l > 0) l--; else r++; }
    }
    const res = new Set();
    const dfs = (i, str, lCount, rCount, lRem, rRem, open) => {
        if (open < 0) return;
        if (i === s.length) {
            if (lRem === 0 && rRem === 0 && open === 0) res.add(str);
            return;
        }
        const c = s[i];
        if (c === '(') {
            dfs(i+1, str + c, lCount+1, rCount, lRem, rRem, open+1);
            if (lRem > 0) dfs(i+1, str, lCount, rCount, lRem-1, rRem, open);
        } else if (c === ')') {
            if (open > 0) dfs(i+1, str + c, lCount, rCount+1, lRem, rRem, open-1);
            if (rRem > 0) dfs(i+1, str, lCount, rCount, lRem, rRem-1, open);
        } else {
            dfs(i+1, str + c, lCount, rCount, lRem, rRem, open);
        }
    };
    dfs(0, '', 0, 0, l, r, 0);
    return [...res];
};
