```javascript
/**
 * @param {number[]} nums
 * @param {number} k
 * @return {number[]}
 */
var medianSlidingWindow = function(nums, k) {
    const n = nums.length;
    const sorted = Array.from(new Set(nums)).sort((a, b) => a - b);
    const m = sorted.length;

    const idxOf = new Map();
    for (let i = 0; i < m; i++) idxOf.set(sorted[i], i + 1);

    const tree = new Int32Array(m + 1);

    const update = (idx, delta) => {
        for (; idx <= m; idx += idx & -idx) tree[idx] += delta;
    };

    // Find the j-th smallest (1-indexed) value currently in the window
    const findKth = (j) => {
        let pos = 0, rem = j;
        for (let pw = 1 << (31 - Math.clz32(m)); pw > 0; pw >>= 1) {
            if (pos + pw <= m && tree[pos + pw] < rem) {
                rem -= tree[pos + pw];
                pos += pw;
            }
        }
        return sorted[pos];
    };

    // Build first window
    for (let i = 0; i < k; i++) update(idxOf.get(nums[i]), 1);

    const res = new Array(n - k + 1);
    const half = k >> 1;
    for (let i = 0; i + k <= n; i++) {
        if (k & 1) {
            res[i] = findKth(half + 1);
        } else {
            res[i] = (findKth(half) + findKth(half + 1)) / 2;
        }
        // Slide the window
        if (i + k < n) {
            update(idxOf.get(nums[i]), -1);
            update(idxOf.get(nums[i + k]), 1);
        }
    }
    return res;
};
```

