var strWithout3a3b = function(a, b) {
    let charA = 'a', charB = 'b';
    let big = a, small = b;
    if (a < b) {
        big = b; small = a;
        charA = 'b'; charB = 'a';  // charA is the majority char
    }
    // big >= small; charA has `big` count, charB has `small` count
    let parts = [];
    let e, k, m;
    if (big <= 2 * small) {
        e = 0;
    } else {
        e = 1;
    }
    k = big - small - 2 * e;
    m = 2 * small - big + 2 * e;
    // k >= 0, m >= 0 guaranteed for valid inputs
    for (let i = 0; i < k; i++) parts.push(charA + charA + charB);
    for (let i = 0; i < m; i++) parts.push(charA + charB);
    if (e === 1) parts.push(charA + charA);
    return parts.join('');
};
```

